ALLOWED_COLS = {"price", "quantity", "discount"}

def above(df, col, threshold):
    if col not in ALLOWED_COLS:
        raise ValueError(f"unsupported column: {col}")
    return df.query(f"`{col}` > @threshold")

INCOMING = Path("raw").resolve()

def compress(name):
    target = (INCOMING / name).resolve()
    if target.parent != INCOMING or not target.is_file():
        raise ValueError("invalid file")
    subprocess.run(["gzip", "-k", str(target)], check=True)
